-- P0-04 explicit migration. Apply only to a new fixture / approved empty database.
-- Lock budget: 5s; no backfill or production startup migration.
SET lock_timeout = '5s';
CREATE SCHEMA core;
CREATE SCHEMA bridge;
CREATE TABLE core.schema_version(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE DOMAIN core.id AS text CHECK (length(VALUE) BETWEEN 1 AND 128 AND btrim(VALUE) <> '');
CREATE DOMAIN core.qq_id AS text CHECK (VALUE ~ '^[1-9][0-9]*$');
CREATE TABLE core.workspace(id core.id PRIMARY KEY);
CREATE TABLE core.principal(workspace_id core.id NOT NULL REFERENCES core.workspace(id), id core.id NOT NULL, permissions jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(workspace_id,id));
CREATE TABLE core.account(
 workspace_id core.id NOT NULL REFERENCES core.workspace(id), id core.id NOT NULL,
 runtime_id core.id NOT NULL, adapter_instance_id core.id NOT NULL, self_id core.qq_id,
 identity_status text NOT NULL DEFAULT 'unverified' CHECK(identity_status IN ('unverified','verified','stale','drift')),
 identity_generation bigint NOT NULL DEFAULT 1 CHECK(identity_generation>0),owner_epoch bigint NOT NULL DEFAULT 1 CHECK(owner_epoch>0),
 connection_state text NOT NULL DEFAULT 'offline' CHECK(connection_state IN ('online','offline','degraded','unknown')),
 login_state text NOT NULL DEFAULT 'unknown' CHECK(login_state IN ('logged_in','logged_out','challenge_required','unknown')),
 control_state text NOT NULL DEFAULT 'paused' CHECK(control_state IN ('active','paused','blocked')),
 risk_state text NOT NULL DEFAULT 'unknown' CHECK(risk_state IN ('clear','restricted','challenge_required','unknown')),
 request_join_verified boolean NOT NULL DEFAULT false,membership_verified boolean NOT NULL DEFAULT false,
 quota_limit integer NOT NULL DEFAULT 1 CHECK(quota_limit>0),next_action_at timestamptz NOT NULL DEFAULT now(),heartbeat_at timestamptz,
 version integer NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,id),
 UNIQUE(workspace_id,runtime_id),UNIQUE(workspace_id,adapter_instance_id),UNIQUE(workspace_id,self_id),
 CHECK(identity_status<>'verified' OR self_id IS NOT NULL));
CREATE TABLE core.runtime_credentials(
 workspace_id core.id NOT NULL,runtime_id core.id NOT NULL,account_id core.id NOT NULL,owner_epoch bigint NOT NULL CHECK(owner_epoch>0),
 membership_authority boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,
 PRIMARY KEY(workspace_id,runtime_id,account_id),FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id));
CREATE TABLE core.runtime_heartbeat(
 workspace_id core.id NOT NULL,runtime_id core.id NOT NULL,account_id core.id NOT NULL,id core.id NOT NULL,
 owner_epoch bigint NOT NULL CHECK(owner_epoch>0),sequence bigint NOT NULL CHECK(sequence>0),
 connection_state text NOT NULL CHECK(connection_state IN ('online','offline','degraded','unknown')),
 login_state text NOT NULL CHECK(login_state IN ('logged_in','logged_out','challenge_required','unknown')),
 heartbeat_at timestamptz NOT NULL,capabilities jsonb NOT NULL CHECK(jsonb_typeof(capabilities)='array' AND jsonb_array_length(capabilities)<=8),
 request_id core.id NOT NULL,digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),
 disposition text NOT NULL CHECK(disposition IN ('applied','stale')),
 accepted_at timestamptz NOT NULL,account_version integer NOT NULL CHECK(account_version>0),
 control_state text NOT NULL CHECK(control_state IN ('active','paused','blocked')),next_action_at timestamptz,
 received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,runtime_id,account_id,owner_epoch,sequence),
 UNIQUE(workspace_id,runtime_id,account_id,request_id),
 FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id));
CREATE TABLE core.heartbeat_idempotency(
 workspace_id core.id NOT NULL,runtime_id core.id NOT NULL,account_id core.id NOT NULL,request_id core.id NOT NULL,
 owner_epoch bigint NOT NULL,sequence bigint NOT NULL,digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(workspace_id,runtime_id,account_id,request_id),
 FOREIGN KEY(workspace_id,runtime_id,account_id,owner_epoch,sequence) REFERENCES core.runtime_heartbeat(workspace_id,runtime_id,account_id,owner_epoch,sequence));
CREATE TABLE core.approval(
 workspace_id core.id NOT NULL,id core.id NOT NULL,principal_id core.id NOT NULL,scope_revision integer NOT NULL CHECK(scope_revision>0),
 action text NOT NULL DEFAULT 'request_join' CHECK(action='request_join'),account_ids text[] NOT NULL,target_ids text[] NOT NULL,
 max_attempts integer NOT NULL CHECK(max_attempts>0),expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,
 PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,principal_id) REFERENCES core.principal(workspace_id,id));
CREATE TABLE core.task(
 workspace_id core.id NOT NULL,id core.id NOT NULL,principal_id core.id NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
 state text NOT NULL CHECK(state IN ('DRAFT','VALIDATING','READY','RUNNING','WAITING_EXTERNAL','BLOCKED','VERIFYING','PAUSING','PAUSED','CANCELLING','CANCELLED','SUCCEEDED','PARTIAL','FAILED')),
 mode text NOT NULL DEFAULT 'dry_run' CHECK(mode IN ('dry_run','read_only','live')),version integer NOT NULL DEFAULT 1 CHECK(version>0),scope_revision integer NOT NULL DEFAULT 1 CHECK(scope_revision>0),
 goal_count integer NOT NULL CHECK(goal_count BETWEEN 1 AND 10000),deadline_at timestamptz NOT NULL,approval_id core.id,
 baseline_complete boolean NOT NULL DEFAULT false,baseline_ref core.id,max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 10),
 max_total_attempts integer NOT NULL CHECK(max_total_attempts BETWEEN 1 AND 10000),candidate_source jsonb NOT NULL,request_payload jsonb NOT NULL,
 import_offset integer NOT NULL DEFAULT 0 CHECK(import_offset>=0),import_done boolean NOT NULL DEFAULT false,event_seq bigint NOT NULL DEFAULT 0 CHECK(event_seq>=0),
 created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),
 FOREIGN KEY(workspace_id,principal_id) REFERENCES core.principal(workspace_id,id),FOREIGN KEY(workspace_id,approval_id) REFERENCES core.approval(workspace_id,id),
 CHECK(jsonb_typeof(candidate_source)='object' AND COALESCE(candidate_source->>'kind','')='fixed' AND COALESCE(jsonb_typeof(candidate_source->'groups'),'null')='array'),CHECK(mode<>'live' OR approval_id IS NOT NULL));
CREATE TABLE core.task_account(workspace_id core.id NOT NULL,task_id core.id NOT NULL,account_id core.id NOT NULL,PRIMARY KEY(workspace_id,task_id,account_id),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id),FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id));
CREATE TABLE core.target(workspace_id core.id NOT NULL REFERENCES core.workspace(id),id core.id NOT NULL,external_id core.qq_id NOT NULL,disabled boolean NOT NULL DEFAULT false,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,external_id));
CREATE TABLE core.task_target(workspace_id core.id NOT NULL,task_id core.id NOT NULL,target_id core.id NOT NULL,source_ref core.id NOT NULL,baseline_covered boolean NOT NULL DEFAULT false,eligibility text NOT NULL DEFAULT 'eligible' CHECK(eligibility IN ('eligible','already_covered','excluded','rejected')),PRIMARY KEY(workspace_id,task_id,target_id),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id),FOREIGN KEY(workspace_id,target_id) REFERENCES core.target(workspace_id,id));
CREATE TABLE core.baseline_account(workspace_id core.id NOT NULL,task_id core.id NOT NULL,account_id core.id NOT NULL,evidence_ref core.id NOT NULL,observed_at timestamptz NOT NULL,complete boolean NOT NULL,PRIMARY KEY(workspace_id,task_id,account_id),FOREIGN KEY(workspace_id,task_id,account_id) REFERENCES core.task_account(workspace_id,task_id,account_id));
CREATE TABLE core.baseline(workspace_id core.id NOT NULL,task_id core.id NOT NULL,account_id core.id NOT NULL,target_external_id core.qq_id NOT NULL,evidence_ref core.id NOT NULL,observed_at timestamptz NOT NULL,PRIMARY KEY(workspace_id,task_id,account_id,target_external_id),FOREIGN KEY(workspace_id,task_id,account_id) REFERENCES core.baseline_account(workspace_id,task_id,account_id));
CREATE TABLE core.subtask(
 workspace_id core.id NOT NULL,id core.id NOT NULL,task_id core.id NOT NULL,target_id core.id NOT NULL,kind text NOT NULL DEFAULT 'ensure_membership' CHECK(kind='ensure_membership'),
 state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','CLAIMED','RUNNING','WAITING_EXTERNAL','RECONCILING','RETRY_WAIT','SUCCEEDED','FAILED','CANCELLED','BLOCKED')),
 assigned_account_id core.id,current_execution_id core.id,fence_token bigint NOT NULL DEFAULT 0 CHECK(fence_token>=0),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),
 max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 10),next_run_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1 CHECK(version>0),
 PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,task_id,target_id,kind),UNIQUE(workspace_id,id,task_id,target_id),
 FOREIGN KEY(workspace_id,task_id,target_id) REFERENCES core.task_target(workspace_id,task_id,target_id),FOREIGN KEY(workspace_id,assigned_account_id) REFERENCES core.account(workspace_id,id),CHECK(attempt_count<=max_attempts));
CREATE TABLE core.execution(
 workspace_id core.id NOT NULL,id core.id NOT NULL,task_id core.id NOT NULL,subtask_id core.id NOT NULL,operation_id core.id NOT NULL,
 account_id core.id NOT NULL,target_id core.id NOT NULL,runtime_id core.id NOT NULL,owner_epoch bigint NOT NULL CHECK(owner_epoch>0),fence_token bigint NOT NULL CHECK(fence_token>0),scope_revision integer NOT NULL CHECK(scope_revision>0),attempt_no integer NOT NULL CHECK(attempt_no>0),
 action text NOT NULL DEFAULT 'request_join' CHECK(action='request_join'),request_digest text NOT NULL CHECK(request_digest ~ '^[a-f0-9]{64}$'),request_payload jsonb NOT NULL,
 state text NOT NULL DEFAULT 'CREATED' CHECK(state IN ('CREATED','ACCEPTED','DISPATCHING','OBSERVED','UNKNOWN','REJECTED_BEFORE_SEND')),
 disposition text CHECK(disposition IN ('confirmed','submitted','pending','rejected','failed_no_effect','unknown')),
 effect_certainty text NOT NULL DEFAULT 'no_effect' CHECK(effect_certainty IN ('no_effect','confirmed','confirmed_submitted','confirmed_rejected','unknown')),
 external_request_ref text,evidence_ref core.id,started_at timestamptz,observed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,operation_id),UNIQUE(workspace_id,subtask_id,attempt_no),
 UNIQUE(workspace_id,id,task_id,target_id,account_id),FOREIGN KEY(workspace_id,subtask_id,task_id,target_id) REFERENCES core.subtask(workspace_id,id,task_id,target_id),
 FOREIGN KEY(workspace_id,task_id,account_id) REFERENCES core.task_account(workspace_id,task_id,account_id),
 CHECK((state IN ('CREATED','ACCEPTED','REJECTED_BEFORE_SEND') AND effect_certainty='no_effect' AND disposition IS NULL) OR (state='DISPATCHING' AND effect_certainty='unknown' AND disposition IS NULL) OR (state='UNKNOWN' AND effect_certainty='unknown' AND disposition='unknown') OR (state='OBSERVED' AND ((disposition IN ('submitted','pending') AND effect_certainty='confirmed_submitted') OR (disposition='confirmed' AND effect_certainty='confirmed') OR (disposition='rejected' AND effect_certainty='confirmed_rejected') OR (disposition='failed_no_effect' AND effect_certainty='no_effect')))));
ALTER TABLE core.subtask ADD FOREIGN KEY(workspace_id,current_execution_id) REFERENCES core.execution(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION core.validate_execution_attempt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE max_attempts integer; current_attempt integer; BEGIN
 SELECT s.max_attempts,s.attempt_count INTO max_attempts,current_attempt FROM core.subtask s WHERE s.workspace_id=NEW.workspace_id AND s.id=NEW.subtask_id AND s.task_id=NEW.task_id AND s.target_id=NEW.target_id;
 IF NOT FOUND OR NEW.attempt_no>max_attempts OR NEW.attempt_no>current_attempt OR current_attempt-NEW.attempt_no>1 THEN RAISE EXCEPTION 'execution attempt exceeds or skips subtask budget' USING ERRCODE='23514'; END IF;
 RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER execution_attempt_budget AFTER INSERT ON core.execution DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core.validate_execution_attempt();
CREATE TABLE core.goal_slot(workspace_id core.id NOT NULL,task_id core.id NOT NULL,slot_no integer NOT NULL CHECK(slot_no>0),state text NOT NULL DEFAULT 'free' CHECK(state IN ('free','reserved','fulfilled')),target_id core.id,reserved_at timestamptz,fulfilled_at timestamptz,PRIMARY KEY(workspace_id,task_id,slot_no),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id),FOREIGN KEY(workspace_id,task_id,target_id) REFERENCES core.task_target(workspace_id,task_id,target_id),CHECK((state='free' AND target_id IS NULL AND reserved_at IS NULL AND fulfilled_at IS NULL) OR (state='reserved' AND target_id IS NOT NULL AND reserved_at IS NOT NULL AND fulfilled_at IS NULL) OR (state='fulfilled' AND target_id IS NOT NULL AND reserved_at IS NOT NULL AND fulfilled_at IS NOT NULL)));
CREATE UNIQUE INDEX goal_slot_active_target ON core.goal_slot(workspace_id,task_id,target_id) WHERE state IN ('reserved','fulfilled');
CREATE TABLE core.target_claim(workspace_id core.id NOT NULL,target_id core.id NOT NULL,action_family text NOT NULL DEFAULT 'group.join' CHECK(action_family='group.join'),task_id core.id NOT NULL,subtask_id core.id NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','resolved')),acquired_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,PRIMARY KEY(workspace_id,target_id,action_family),FOREIGN KEY(workspace_id,subtask_id,task_id,target_id) REFERENCES core.subtask(workspace_id,id,task_id,target_id),CHECK((state='active' AND resolved_at IS NULL) OR (state='resolved' AND resolved_at IS NOT NULL)));
CREATE TABLE core.account_usage(workspace_id core.id NOT NULL,account_id core.id NOT NULL,action_family text NOT NULL DEFAULT 'group.join' CHECK(action_family='group.join'),window_start date NOT NULL DEFAULT current_date,reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0),consumed integer NOT NULL DEFAULT 0 CHECK(consumed>=0),PRIMARY KEY(workspace_id,account_id,action_family,window_start),FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id));
CREATE TABLE core.dispatch_permit(workspace_id core.id NOT NULL,id core.id NOT NULL,execution_id core.id NOT NULL,operation_id core.id NOT NULL,account_id core.id NOT NULL,target_id core.id NOT NULL,request_digest text NOT NULL,scope_revision integer NOT NULL CHECK(scope_revision>0),owner_epoch bigint NOT NULL CHECK(owner_epoch>0),fence_token bigint NOT NULL CHECK(fence_token>0),issued_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'issued' CHECK(state IN ('issued','consumed','expired')),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,execution_id),UNIQUE(workspace_id,operation_id),FOREIGN KEY(workspace_id,execution_id) REFERENCES core.execution(workspace_id,id),CHECK(expires_at>issued_at));
CREATE TABLE core.account_action_lock(workspace_id core.id NOT NULL,account_id core.id NOT NULL,action_family text NOT NULL DEFAULT 'group.join' CHECK(action_family='group.join'),execution_id core.id NOT NULL,permit_id core.id,held boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL,PRIMARY KEY(workspace_id,account_id,action_family),FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id),FOREIGN KEY(workspace_id,execution_id) REFERENCES core.execution(workspace_id,id),FOREIGN KEY(workspace_id,permit_id) REFERENCES core.dispatch_permit(workspace_id,id));
CREATE TABLE core.inbox(workspace_id core.id NOT NULL,source_runtime_id core.id NOT NULL,event_id core.id NOT NULL,source_account_id core.id NOT NULL,source_epoch bigint NOT NULL CHECK(source_epoch>0),source_sequence bigint NOT NULL CHECK(source_sequence>0),operation_id core.id,target_id core.id NOT NULL,kind text NOT NULL CHECK(kind IN ('membership.observed','operation.observed','join_request.observed')),state text NOT NULL,snapshot_complete boolean NOT NULL,observed_at timestamptz NOT NULL,evidence_ref core.id NOT NULL,digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,apply_state text NOT NULL DEFAULT 'pending' CHECK(apply_state IN ('pending','applied','failed','reconcile')),error_code text,applied_at timestamptz,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,source_runtime_id,event_id),UNIQUE(workspace_id,source_runtime_id,source_account_id,source_epoch,source_sequence),FOREIGN KEY(workspace_id,source_account_id) REFERENCES core.account(workspace_id,id),FOREIGN KEY(workspace_id,target_id) REFERENCES core.target(workspace_id,id),CHECK((kind='membership.observed' AND state IN ('joined','not_joined','unknown')) OR (kind IN ('operation.observed','join_request.observed') AND state IN ('submitted','pending','rejected','failed_no_effect','unknown','confirmed'))));
CREATE TABLE core.observation_conflict(workspace_id core.id NOT NULL,id core.id NOT NULL,source_runtime_id core.id NOT NULL,incoming_event_id core.id NOT NULL,stored_event_id core.id NOT NULL,conflict_kind text NOT NULL CHECK(conflict_kind IN ('event_digest','source_position')),incoming_digest text NOT NULL CHECK(incoming_digest ~ '^[a-f0-9]{64}$'),stored_digest text NOT NULL CHECK(stored_digest ~ '^[a-f0-9]{64}$'),incoming_payload jsonb NOT NULL,stored_payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,source_runtime_id,stored_event_id) REFERENCES core.inbox(workspace_id,source_runtime_id,event_id));
CREATE TABLE core.membership(workspace_id core.id NOT NULL,account_id core.id NOT NULL,target_id core.id NOT NULL,state text NOT NULL CHECK(state IN ('joined','not_joined','unknown')),observed_at timestamptz NOT NULL,evidence_ref core.id NOT NULL,source_runtime_id core.id NOT NULL,source_event_id core.id NOT NULL,PRIMARY KEY(workspace_id,account_id,target_id),FOREIGN KEY(workspace_id,account_id) REFERENCES core.account(workspace_id,id),FOREIGN KEY(workspace_id,target_id) REFERENCES core.target(workspace_id,id),FOREIGN KEY(workspace_id,source_runtime_id,source_event_id) REFERENCES core.inbox(workspace_id,source_runtime_id,event_id));
CREATE TABLE core.result(workspace_id core.id NOT NULL,id core.id NOT NULL,task_id core.id NOT NULL,target_id core.id NOT NULL,account_id core.id NOT NULL,execution_id core.id NOT NULL,source_runtime_id core.id NOT NULL,source_event_id core.id NOT NULL,valid boolean NOT NULL DEFAULT true,evidence_ref core.id NOT NULL,confirmed_at timestamptz NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,task_id,target_id),FOREIGN KEY(workspace_id,execution_id,task_id,target_id,account_id) REFERENCES core.execution(workspace_id,id,task_id,target_id,account_id),FOREIGN KEY(workspace_id,source_runtime_id,source_event_id) REFERENCES core.inbox(workspace_id,source_runtime_id,event_id));
CREATE TABLE core.retry(workspace_id core.id NOT NULL,id core.id NOT NULL,task_id core.id NOT NULL,subtask_id core.id NOT NULL,previous_execution_id core.id NOT NULL,strategy text NOT NULL CHECK(strategy IN ('same_account','reselect')),reason_code text NOT NULL,due_at timestamptz NOT NULL,state text NOT NULL CHECK(state IN ('scheduled','consumed','cancelled')),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id),FOREIGN KEY(workspace_id,subtask_id) REFERENCES core.subtask(workspace_id,id),FOREIGN KEY(workspace_id,previous_execution_id) REFERENCES core.execution(workspace_id,id));
CREATE UNIQUE INDEX retry_one_scheduled ON core.retry(workspace_id,subtask_id) WHERE state='scheduled';
CREATE TABLE core.task_event(workspace_id core.id NOT NULL,task_id core.id NOT NULL,seq bigint NOT NULL CHECK(seq>0),id core.id NOT NULL,kind text NOT NULL,actor text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,task_id,seq),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id));
CREATE TABLE core.outbox(workspace_id core.id NOT NULL,id core.id NOT NULL,task_id core.id NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','delivering','delivered')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_until timestamptz,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,task_id) REFERENCES core.task(workspace_id,id));
CREATE TABLE core.idempotency(workspace_id core.id NOT NULL,principal_id core.id NOT NULL,method text NOT NULL,path text NOT NULL,key text NOT NULL CHECK(length(key) BETWEEN 1 AND 128),digest text NOT NULL CHECK(digest ~ '^[a-f0-9]{64}$'),resource_id core.id NOT NULL,response jsonb NOT NULL,PRIMARY KEY(workspace_id,principal_id,method,path,key),FOREIGN KEY(workspace_id,principal_id) REFERENCES core.principal(workspace_id,id));
CREATE TABLE bridge.gateway_operation(workspace_id text NOT NULL,operation_id text NOT NULL,execution_id text NOT NULL,task_id text NOT NULL,subtask_id text NOT NULL,account_id text NOT NULL,target_id text NOT NULL,runtime_id text NOT NULL,owner_epoch bigint NOT NULL CHECK(owner_epoch>0),fence_token bigint NOT NULL CHECK(fence_token>0),scope_revision integer NOT NULL CHECK(scope_revision>0),request_digest text NOT NULL CHECK(request_digest ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,state text NOT NULL DEFAULT 'ACCEPTED' CHECK(state IN ('ACCEPTED','DISPATCHING','OBSERVED','UNKNOWN','REJECTED_BEFORE_SEND')),disposition text,effect_certainty text NOT NULL DEFAULT 'no_effect',permit_id text,response jsonb,evidence_ref text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,operation_id),CHECK((state IN ('ACCEPTED','REJECTED_BEFORE_SEND') AND effect_certainty='no_effect' AND disposition IS NULL) OR (state='DISPATCHING' AND effect_certainty='unknown' AND disposition IS NULL) OR (state='UNKNOWN' AND effect_certainty='unknown' AND disposition='unknown') OR (state='OBSERVED' AND ((disposition IN ('submitted','pending') AND effect_certainty='confirmed_submitted') OR (disposition='confirmed' AND effect_certainty='confirmed') OR (disposition='rejected' AND effect_certainty='confirmed_rejected') OR (disposition='failed_no_effect' AND effect_certainty='no_effect')))));
CREATE TABLE bridge.outbox(workspace_id text NOT NULL,id text NOT NULL,operation_id text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','delivering','delivered')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,operation_id) REFERENCES bridge.gateway_operation(workspace_id,operation_id));
CREATE INDEX subtask_ready ON core.subtask(state,next_run_at,workspace_id,task_id);
CREATE INDEX execution_account_state ON core.execution(workspace_id,account_id,state);
CREATE INDEX outbox_ready ON core.outbox(state,next_attempt_at);
CREATE INDEX inbox_pending ON core.inbox(apply_state,received_at);
CREATE FUNCTION core.immutable_execution() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['state','disposition','effect_certainty','external_request_ref','evidence_ref','started_at','observed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','disposition','effect_certainty','external_request_ref','evidence_ref','started_at','observed_at']) THEN RAISE EXCEPTION 'immutable execution request' USING ERRCODE='23514'; END IF;
 IF OLD.effect_certainty IN ('unknown','confirmed_submitted','confirmed') OR OLD.state IN ('DISPATCHING','UNKNOWN') THEN
  IF NEW.effect_certainty IN ('unknown','confirmed_submitted') THEN
   NULL;
  ELSIF NEW.effect_certainty='no_effect' THEN
   IF NOT EXISTS(SELECT 1 FROM bridge.gateway_operation g WHERE g.workspace_id=OLD.workspace_id AND g.operation_id=OLD.operation_id AND g.state='OBSERVED' AND g.disposition='failed_no_effect' AND g.effect_certainty='no_effect' AND g.evidence_ref IS NOT NULL AND btrim(g.evidence_ref)<>'') THEN RAISE EXCEPTION 'uncertain effect cannot become no_effect without dispatcher proof' USING ERRCODE='23514'; END IF;
  ELSIF NEW.effect_certainty='confirmed' AND NEW.disposition='confirmed' THEN
   IF NOT EXISTS(SELECT 1 FROM bridge.gateway_operation g WHERE g.workspace_id=OLD.workspace_id AND g.operation_id=OLD.operation_id AND g.state='OBSERVED' AND g.disposition='confirmed' AND g.effect_certainty='confirmed' AND g.evidence_ref IS NOT NULL AND btrim(g.evidence_ref)<>'') AND NOT EXISTS(SELECT 1 FROM core.inbox i WHERE i.workspace_id=OLD.workspace_id AND i.operation_id=OLD.operation_id AND i.source_runtime_id=OLD.runtime_id AND i.source_account_id=OLD.account_id AND i.source_epoch=OLD.owner_epoch AND i.target_id=OLD.target_id AND ((i.kind IN ('operation.observed','join_request.observed') AND i.state='confirmed' AND i.apply_state='applied') OR (i.kind='membership.observed' AND i.state='joined' AND i.snapshot_complete AND i.apply_state='applied' AND NOT EXISTS(SELECT 1 FROM core.inbox newer WHERE newer.workspace_id=i.workspace_id AND newer.source_account_id=i.source_account_id AND newer.target_id=i.target_id AND newer.kind='membership.observed' AND (newer.source_epoch>i.source_epoch OR (newer.source_epoch=i.source_epoch AND newer.source_sequence>i.source_sequence))))) AND i.evidence_ref IS NOT NULL) THEN RAISE EXCEPTION 'confirmed effect requires authoritative bridge or membership evidence' USING ERRCODE='23514'; END IF;
  ELSIF NEW.effect_certainty='confirmed_rejected' AND NEW.disposition='rejected' THEN
   IF NOT EXISTS(SELECT 1 FROM bridge.gateway_operation g WHERE g.workspace_id=OLD.workspace_id AND g.operation_id=OLD.operation_id AND g.state='OBSERVED' AND g.disposition='rejected' AND g.effect_certainty='confirmed_rejected' AND g.evidence_ref IS NOT NULL AND btrim(g.evidence_ref)<>'') AND NOT EXISTS(SELECT 1 FROM core.inbox i WHERE i.workspace_id=OLD.workspace_id AND i.operation_id=OLD.operation_id AND i.source_runtime_id=OLD.runtime_id AND i.source_account_id=OLD.account_id AND i.source_epoch=OLD.owner_epoch AND i.target_id=OLD.target_id AND i.kind IN ('operation.observed','join_request.observed') AND i.state='rejected' AND i.apply_state='applied' AND i.evidence_ref IS NOT NULL) THEN RAISE EXCEPTION 'rejection requires authoritative outcome evidence' USING ERRCODE='23514'; END IF;
  ELSE
   RAISE EXCEPTION 'uncertain effect cannot be weakened' USING ERRCODE='23514';
  END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER execution_immutable BEFORE UPDATE OR DELETE ON core.execution FOR EACH ROW EXECUTE FUNCTION core.immutable_execution();
CREATE FUNCTION core.immutable_dispatch_permit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['state']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state']) THEN RAISE EXCEPTION 'dispatch permit identity is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.state<>'issued' AND NEW.state<>OLD.state THEN RAISE EXCEPTION 'terminal dispatch permit state is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.state='issued' AND NEW.state NOT IN ('issued','consumed','expired') THEN RAISE EXCEPTION 'invalid dispatch permit transition' USING ERRCODE='23514'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER dispatch_permit_immutable BEFORE UPDATE OR DELETE ON core.dispatch_permit FOR EACH ROW EXECUTE FUNCTION core.immutable_dispatch_permit();
CREATE FUNCTION bridge.immutable_operation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['state','disposition','effect_certainty','permit_id','response','evidence_ref','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','disposition','effect_certainty','permit_id','response','evidence_ref','updated_at']) THEN RAISE EXCEPTION 'immutable bridge operation' USING ERRCODE='23514'; END IF;
 IF OLD.state IN ('OBSERVED','UNKNOWN','REJECTED_BEFORE_SEND') AND NEW.state='DISPATCHING' THEN RAISE EXCEPTION 'bridge operation cannot be replayed' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER operation_immutable BEFORE UPDATE OR DELETE ON bridge.gateway_operation FOR EACH ROW EXECUTE FUNCTION bridge.immutable_operation();
CREATE FUNCTION core.append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'persistent audit is append only' USING ERRCODE='23514'; END $$;
CREATE TRIGGER task_event_append_only BEFORE UPDATE OR DELETE ON core.task_event FOR EACH ROW EXECUTE FUNCTION core.append_only();
CREATE TRIGGER observation_conflict_append_only BEFORE UPDATE OR DELETE ON core.observation_conflict FOR EACH ROW EXECUTE FUNCTION core.append_only();
CREATE TRIGGER runtime_heartbeat_append_only BEFORE UPDATE OR DELETE ON core.runtime_heartbeat FOR EACH ROW EXECUTE FUNCTION core.append_only();
CREATE TRIGGER heartbeat_idempotency_append_only BEFORE UPDATE OR DELETE ON core.heartbeat_idempotency FOR EACH ROW EXECUTE FUNCTION core.append_only();
CREATE FUNCTION core.result_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'result evidence is append only; invalidate instead of deleting' USING ERRCODE='23514'; END $$;
CREATE TRIGGER result_no_delete BEFORE DELETE ON core.result FOR EACH ROW EXECUTE FUNCTION core.result_guard();
CREATE FUNCTION core.execution_retains_holds(w text,t text,g text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM core.execution e WHERE e.workspace_id=w AND e.task_id=t AND e.target_id=g AND (e.state IN ('DISPATCHING','UNKNOWN') OR e.effect_certainty IN ('unknown','confirmed_submitted') OR (e.effect_certainty='confirmed' AND NOT EXISTS(SELECT 1 FROM core.result r WHERE r.workspace_id=e.workspace_id AND r.task_id=e.task_id AND r.target_id=e.target_id AND r.valid) AND NOT EXISTS(SELECT 1 FROM core.membership m WHERE m.workspace_id=e.workspace_id AND m.account_id=e.account_id AND m.target_id=e.target_id AND m.state='not_joined' AND m.observed_at>=COALESCE(e.observed_at,e.started_at))))) $$;
CREATE FUNCTION core.slot_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE goal integer; BEGIN
 IF TG_OP<>'DELETE' THEN SELECT goal_count INTO goal FROM core.task WHERE workspace_id=NEW.workspace_id AND id=NEW.task_id FOR UPDATE; IF NEW.slot_no>goal THEN RAISE EXCEPTION 'slot exceeds task goal' USING ERRCODE='23514'; END IF; END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND OLD.target_id IS NOT NULL AND (TG_OP='DELETE' OR NEW.target_id IS DISTINCT FROM OLD.target_id OR NEW.state='free') AND core.execution_retains_holds(OLD.workspace_id,OLD.task_id,OLD.target_id) THEN RAISE EXCEPTION 'unresolved external effect retains goal slot' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER slot_guard BEFORE INSERT OR UPDATE OR DELETE ON core.goal_slot FOR EACH ROW EXECUTE FUNCTION core.slot_guard();
CREATE FUNCTION core.claim_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP IN ('UPDATE','DELETE') AND OLD.state='active' AND (TG_OP='DELETE' OR NEW.state<>'active' OR NEW.task_id IS DISTINCT FROM OLD.task_id OR NEW.subtask_id IS DISTINCT FROM OLD.subtask_id) AND core.execution_retains_holds(OLD.workspace_id,OLD.task_id,OLD.target_id) THEN RAISE EXCEPTION 'unresolved external effect retains target claim' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER claim_guard BEFORE UPDATE OR DELETE ON core.target_claim FOR EACH ROW EXECUTE FUNCTION core.claim_guard();
CREATE FUNCTION core.verify_state_closure() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE w text; t text; BEGIN
 w:=NEW.workspace_id; IF TG_TABLE_NAME='task' THEN t:=NEW.id; ELSE t:=NEW.task_id; END IF;
 PERFORM 1 FROM core.task WHERE workspace_id=w AND id=t FOR UPDATE;
 IF EXISTS(SELECT 1 FROM core.execution e WHERE e.workspace_id=w AND e.task_id=t AND core.execution_retains_holds(w,t,e.target_id) AND (NOT EXISTS(SELECT 1 FROM core.goal_slot s WHERE s.workspace_id=w AND s.task_id=t AND s.target_id=e.target_id AND s.state IN ('reserved','fulfilled')) OR NOT EXISTS(SELECT 1 FROM core.target_claim c WHERE c.workspace_id=w AND c.target_id=e.target_id AND c.task_id=t AND c.subtask_id=e.subtask_id AND c.state='active'))) THEN RAISE EXCEPTION 'possible external effect needs slot and claim' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM core.goal_slot s WHERE s.workspace_id=w AND s.task_id=t AND s.state='fulfilled' AND NOT EXISTS(SELECT 1 FROM core.result r WHERE r.workspace_id=w AND r.task_id=t AND r.target_id=s.target_id AND r.valid)) THEN RAISE EXCEPTION 'fulfilled slot requires trusted result' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM core.result r JOIN core.execution e ON (e.workspace_id,e.id)=(r.workspace_id,r.execution_id) JOIN core.task k ON (k.workspace_id,k.id)=(r.workspace_id,r.task_id) JOIN core.task_target tt ON (tt.workspace_id,tt.task_id,tt.target_id)=(r.workspace_id,r.task_id,r.target_id) WHERE r.workspace_id=w AND r.task_id=t AND r.valid AND (tt.baseline_covered OR e.state<>'OBSERVED' OR e.disposition<>'confirmed' OR e.scope_revision<>k.scope_revision OR NOT EXISTS(SELECT 1 FROM core.inbox i JOIN core.runtime_credentials rc ON (rc.workspace_id,rc.runtime_id,rc.account_id)=(i.workspace_id,i.source_runtime_id,i.source_account_id) WHERE (i.workspace_id,i.source_runtime_id,i.event_id)=(r.workspace_id,r.source_runtime_id,r.source_event_id) AND i.kind='membership.observed' AND i.state='joined' AND i.snapshot_complete AND i.apply_state='applied' AND i.source_account_id=r.account_id AND i.target_id=r.target_id AND i.operation_id=e.operation_id AND i.source_runtime_id=e.runtime_id AND i.source_epoch=e.owner_epoch AND rc.membership_authority AND i.observed_at>=e.started_at AND i.observed_at<=clock_timestamp()+interval '5 seconds' AND NOT EXISTS(SELECT 1 FROM core.inbox newer WHERE newer.workspace_id=i.workspace_id AND newer.source_runtime_id=i.source_runtime_id AND newer.source_account_id=i.source_account_id AND newer.source_epoch=i.source_epoch AND newer.source_sequence>i.source_sequence AND newer.target_id=i.target_id AND newer.kind='membership.observed' AND k.state NOT IN ('CANCELLED','SUCCEEDED','PARTIAL','FAILED'))) OR NOT EXISTS(SELECT 1 FROM core.dispatch_permit p WHERE p.workspace_id=w AND p.execution_id=e.id AND p.operation_id=e.operation_id AND p.account_id=e.account_id AND p.target_id=e.target_id AND p.request_digest=e.request_digest AND p.scope_revision=e.scope_revision AND p.owner_epoch=e.owner_epoch AND p.fence_token=e.fence_token AND p.state='consumed'))) THEN RAISE EXCEPTION 'success requires confirmed operation and trusted correlated joined membership' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM core.task k WHERE k.workspace_id=w AND k.id=t AND k.state='SUCCEEDED' AND (k.goal_count<>(SELECT count(*) FROM core.result r WHERE r.workspace_id=w AND r.task_id=t AND r.valid) OR EXISTS(SELECT 1 FROM core.goal_slot s WHERE s.workspace_id=w AND s.task_id=t AND s.state<>'fulfilled'))) THEN RAISE EXCEPTION 'task success requires complete results' USING ERRCODE='23514'; END IF;
 RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER execution_closure AFTER INSERT OR UPDATE ON core.execution DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core.verify_state_closure();
CREATE CONSTRAINT TRIGGER slot_closure AFTER INSERT OR UPDATE ON core.goal_slot DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core.verify_state_closure();
CREATE CONSTRAINT TRIGGER result_closure AFTER INSERT OR UPDATE ON core.result DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core.verify_state_closure();
CREATE CONSTRAINT TRIGGER task_closure AFTER INSERT OR UPDATE ON core.task DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION core.verify_state_closure();
CREATE FUNCTION core.retry_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.state='scheduled' AND NOT EXISTS(SELECT 1 FROM core.execution e JOIN bridge.gateway_operation g ON (g.workspace_id,g.operation_id)=(e.workspace_id,e.operation_id) JOIN core.subtask s ON (s.workspace_id,s.id)=(e.workspace_id,e.subtask_id) WHERE e.workspace_id=NEW.workspace_id AND e.id=NEW.previous_execution_id AND e.subtask_id=NEW.subtask_id AND e.task_id=NEW.task_id AND e.state='OBSERVED' AND e.effect_certainty='no_effect' AND e.disposition='failed_no_effect' AND g.state='OBSERVED' AND g.disposition='failed_no_effect' AND g.evidence_ref IS NOT NULL AND s.attempt_count<s.max_attempts AND NOT EXISTS(SELECT 1 FROM core.account_action_lock l WHERE l.workspace_id=e.workspace_id AND l.execution_id=e.id AND l.held)) THEN RAISE EXCEPTION 'retry requires completed technical no-effect proof and remaining logical budget' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER retry_guard BEFORE INSERT OR UPDATE ON core.retry FOR EACH ROW EXECUTE FUNCTION core.retry_guard();
